--- a/gateway/src/proxy/stream_buffer.rs
+++ b/gateway/src/proxy/stream_buffer.rs
@@ -12,7 +12,22 @@
-const FIXED_BUFFER_BYTES: usize = 65536;
+// Adaptive buffer that increases flush aggressiveness when chunk latency grows
+const MIN_FLUSH_MS: u64 = 10;
+const MAX_FLUSH_MS: u64 = 250;
+// Threshold is scaled by observed inter-chunk latency and RSS; configurable at runtime
+// to avoid stalls when backend emits irregularly-sized chunks (e.g. function call markers)
+fn should_flush(inter_chunk_ms: u64, rss: usize) -> bool {
+    let dynamic_threshold = ((inter_chunk_ms as f64) * 1.5) as u64;
+    return inter_chunk_ms >= std::cmp::min(dynamic_threshold, MAX_FLUSH_MS);
+}
